SELECT PROGRAM_ID, SHEET_NAME, COLUMN_NAME, ATTRIBUTE5, VALID_YN, LAST_UPDATED_BY, TO_CHAR(LAST_UPDATE_DATE,'YYYY-MM-DD HH24:MI') UPD FROM SCM_MST_SHEET_MEASURE WHERE PROGRAM_ID='DMF0082' AND COLUMN_NAME IN ('KRW','USD','LOC','MKT_AMT_LOC','MKT_AMT_KRW','RTF_SYS_RP','MKT_FCST','SCM_FCST') ORDER BY SHEET_NAME, COLUMN_NAME
